INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('react-vite', 1, 'frontend', 'tool', 'React＋Vite', '管理画面や業務システムなど、操作性の高いWeb画面を短期間で構築する', '{"overview":"ReactをViteで動かす構成。Viteの高速な開発サーバーとHMRにより、コーディング中の変更が即座に画面へ反映される。","fit":"SPA（シングルページアプリ）として管理画面や業務システムを素早く立ち上げたい場合に向く。エコシステムが豊富でライブラリ選定の自由度が高い。","caution":"SSRやSEO対応ができないわけではないが、標準的なSPA構成では追加設計が必要。検索流入を重視する公開サイトでは、Next.jsやAstroなどの構成と比較して選定する。","url":"https://vite.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nextjs', 1, 'frontend', 'tool', 'Next.js', 'Web画面、サーバー処理、SEO対応ページを一つの構成で開発する', '{"overview":"Reactベースのフルスタックフレームワーク。ページ生成方式（SSR・SSG・ISR）を切り替えられ、サーバー処理もアプリ内に統合できる。","fit":"SEOが重要な公開サービスや、フロントとバックエンドを一つのコードベースで開発したいSaaSに向く。","caution":"設定項目やレンダリング方式の選択肢が多く、React単体の構成に比べて学習コストがやや高い。","url":"https://nextjs.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('vue-vite', 1, 'frontend', 'tool', 'Vue＋Vite', 'Vueを使って、管理画面や小規模Webアプリを軽量に構築する', '{"overview":"VueをViteで動かす構成。Reactに比べテンプレート構文が直感的で、学習コストを抑えやすい。","fit":"管理画面や小規模なWebアプリを、少人数・短期間で構築したい場合に向く。","caution":"Reactと比べると、利用できるライブラリや採用人材の選択肢が少ない分野もある。長期運用する場合は、チーム内のVue経験者や保守体制を確認する。","url":"https://vuejs.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nuxt', 1, 'frontend', 'tool', 'Nuxt', 'Vueを使って、SEOやサーバー処理を含むWebサービスを構築する', '{"overview":"VueをベースにしたフルスタックWebフレームワーク。SSR・SSG・サーバーAPIなどを一つのプロジェクト内で構築できる。","fit":"SEOを重視するWebサービスをVueで作りたい場合に適する。","caution":"Nuxt特有のディレクトリ規約やモジュールエコシステムを理解する必要がある。","url":"https://nuxt.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('sveltekit', 1, 'frontend', 'tool', 'SvelteKit', '少ないコード量で、軽量なWebサービスを構築する', '{"overview":"Svelteをベースにしたフレームワーク。コンパイル時に処理を最適化するため、ランタイムが軽量。","fit":"パフォーマンスを重視した軽量なWebサービスに向く。コード量も少なく済む。","caution":"React・Vueに比べエコシステムや求人市場が小さく、長期保守での人材調達リスクがある。","url":"https://svelte.dev/docs/kit"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('angular', 1, 'frontend', 'tool', 'Angular', '大規模な企業向け管理画面や、構造化されたWebアプリを構築する', '{"overview":"Googleが開発するフルスタック指向のフロントエンドフレームワーク。TypeScript前提で、DIやルーティングが標準装備。","fit":"大規模な企業向けシステムなど、厳格な設計規約とチーム開発の統制が必要な場面に向く。","caution":"学習コストが高く、小規模プロジェクトにはオーバースペックになりやすい。","url":"https://angular.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('blazor', 1, 'frontend', 'tool', 'Blazor', 'C#を使って企業向けWebシステムを構築する', '{"overview":"C#でフロントエンドを記述できるMicrosoftのフレームワーク。WebAssemblyまたはサーバー側処理で動作する。","fit":".NET・C#の資産やスキルセットを持つ企業向けシステムに向く。","caution":"JS系フレームワークに比べエコシステムが小さく、非Microsoft環境との親和性は低め。","url":"https://dotnet.microsoft.com/en-us/apps/aspnet/web-apps/blazor"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('pwa', 1, 'frontend', 'tool', 'PWA', 'Webアプリをスマートフォンアプリに近い操作感で利用し、オフラインにも対応する', '{"overview":"Webアプリをホーム画面への追加やオフライン動作、プッシュ通知などネイティブアプリに近い形で使える技術。特定のフレームワークではなく、既存のWeb画面に追加する機能。","fit":"アプリストア審査を経ずに、スマートフォンでアプリのような操作感を提供したい場合に向く。","caution":"iOSでもホーム画面に追加したWebアプリでプッシュ通知を利用できるが、インストール導線、バックグラウンド処理、BluetoothやNFCなど、一部機能はOS・ブラウザによって対応状況が異なる。","url":"https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('astro', 1, 'frontend', 'tool', 'Astro', '企業サイト、メディア、ドキュメントサイトを高速かつSEOに強い構成で開発する', '{"overview":"コンテンツ中心のWebサイトに適したフレームワーク。基本部分を静的HTMLとして生成し、必要な箇所だけにReactやVueなどのJavaScriptを読み込む「アイランド構成」を採用できる。","fit":"コーポレートサイト、オウンドメディア、技術ドキュメント、ランディングページなど、表示速度とSEOを重視するWebサイトに向く。","caution":"画面全体が頻繁に変化する管理画面や、複雑な状態管理を持つSaaSでは、Next.jsやReact SPAの方が設計しやすい場合がある。","url":"https://astro.build/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('shadcn-ui', 1, 'ui-design', 'tool', 'shadcn/ui', 'Reactの画面に、コピー&ペーストで組み込める高品質なUIコンポーネント群を追加する', '{"overview":"Radix UIをベースにした、あらかじめスタイリングされたコンポーネント集。npmパッケージとしてではなく、ソースコードを直接プロジェクトへコピーして使う点が特徴。","fit":"デザインを自由にカスタマイズしたい、Tailwind CSSを使ったReactプロジェクトに向く。","caution":"通常のnpmパッケージと異なりコンポーネントのアップデートは手動反映が必要。Tailwind CSS前提のため、他のCSS設計との併用にはひと手間かかる。","url":"https://ui.shadcn.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('mui', 1, 'ui-design', 'tool', 'MUI', 'Material Designに準拠した、完成度の高いUIコンポーネント一式をReactに導入する', '{"overview":"Googleが提唱するMaterial Designに基づいたReact向けUIライブラリ。フォーム、テーブル、ダイアログなど業務画面に必要な部品がほぼ揃っている。","fit":"デザインを一から作り込む時間がなく、統一感のある管理画面を素早く構築したい業務システムに向く。","caution":"Material Design特有の見た目になりやすく、独自ブランドの世界観を強く出したい場合はカスタマイズの手間が増える。","url":"https://mui.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('chakra-ui', 1, 'ui-design', 'tool', 'Chakra UI', 'アクセシビリティを重視した、React向けの組み立てやすいUIコンポーネント群を導入する', '{"overview":"アクセシビリティ対応とスタイルの組み合わせやすさを重視したReact UIライブラリ。propsベースで見た目を柔軟に調整できる。","fit":"アクセシビリティ品質を確保しつつ、独自のデザインにも寄せたいプロジェクトに向く。","caution":"MUIほど業務向けの高機能コンポーネント（高度なテーブル等）は揃っておらず、複雑な部品は自作が必要になることがある。","url":"https://www.chakra-ui.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('ant-design', 1, 'ui-design', 'tool', 'Ant Design', '業務システム向けに作り込まれた、フォーム・テーブルが充実したUIコンポーネント一式を導入する', '{"overview":"中国Alibabaが開発する、エンタープライズ業務システム向けのReact UIライブラリ。高機能なテーブルやフォームバリデーションが標準で揃う。","fit":"管理画面・業務システムなど、複雑な一覧表示や入力フォームを多く扱うシステムに向く。","caution":"デザインの独自性を出しにくく、コンポーネントの見た目のカスタマイズ自由度はMUIやChakra UIよりも低め。","url":"https://ant.design/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('radix-ui', 1, 'ui-design', 'tool', 'Radix UI', '見た目を持たない、アクセシビリティ対応済みのUI部品（プリミティブ）を導入する', '{"overview":"ダイアログやドロップダウンなど、操作・アクセシビリティのロジックだけを提供し、見た目は一切持たないUIプリミティブ集。shadcn/uiの内部でも採用されている。","fit":"独自デザインシステムをゼロから構築したいプロジェクトで、複雑な操作ロジック（フォーカス管理等）だけを任せたい場合に向く。","caution":"見た目のスタイリングはすべて自前で行う必要があり、MUIやAnt Designのようにすぐ使える完成品ではない。","url":"https://www.radix-ui.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('vuetify', 1, 'ui-design', 'tool', 'Vuetify', 'Material Designに準拠した、Vue向けのUIコンポーネント一式を導入する', '{"overview":"Vue.js向けのMaterial Design UIライブラリ。フォーム、ナビゲーション、レイアウトなど画面部品が豊富に揃う。","fit":"Vueを採用したプロジェクトで、デザインを作り込まずに統一感のある画面を構築したい場合に向く。","caution":"Material Designの見た目が前面に出やすく、独自ブランドを強く出したい場合はカスタマイズが必要。","url":"https://vuetifyjs.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('angular-material', 1, 'ui-design', 'tool', 'Angular Material', 'Angular公式が提供する、Material Design準拠のUIコンポーネント一式を導入する', '{"overview":"Angularチームが公式にメンテナンスするUIコンポーネントライブラリ。Angularのフォーム機能やアクセシビリティ機能と統合されている。","fit":"Angularを採用した企業システムで、公式サポートのある安定したUI部品を使いたい場合に向く。","caution":"Angular専用のため、他のフレームワークへの移植や流用はできない。","url":"https://material.angular.io/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('tailwind-css', 1, 'ui-design', 'tool', 'Tailwind CSS', 'あらかじめ用意されたユーティリティクラスを組み合わせて、独自デザインの画面を効率よく構築する', '{"overview":"コンポーネント集ではなく、余白・色・文字サイズなどをクラス名の組み合わせで指定するユーティリティファーストのCSSフレームワーク。","fit":"既製のデザインに縛られず、独自のデザインシステムを効率的にコーディングしたい、ほぼすべてのフロントエンド構成に向く。","caution":"コンポーネントの機能（操作ロジック）自体は提供しないため、複雑な部品はshadcn/uiやRadix UIなど別のライブラリと組み合わせるのが一般的。","url":"https://tailwindcss.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('bootstrap', 1, 'ui-design', 'tool', 'Bootstrap', '長年の実績があるCSS・UIコンポーネント一式を、フレームワークを問わず導入する', '{"overview":"古くから使われている定番のUIフレームワーク。CSSクラスとJavaScriptで構成され、特定のJSフレームワークに依存せず利用できる。","fit":"特定のJSフレームワークに縛られない社内ツールや、素早く見た目を整えたい小規模なシステムに向く。","caution":"近年のReact/Vue中心の開発では、コンポーネント志向の他ライブラリに比べて設計思想がやや古く感じられることがある。","url":"https://getbootstrap.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('flutter', 1, 'mobile-desktop', 'tool', 'Flutter', 'iOS、Android、Webで利用できるアプリを共通コードで開発する', '{"overview":"Googleが開発するUIフレームワーク。単一のコードベースでiOS・Android・Webの画面を構築できる。","fit":"複数プラットフォームを同時にリリースしたい場合や、デザインの統一性を重視する場合に向く。","caution":"Dartという専用言語の習得が必要で、ネイティブ機能を深く使う場合はプラグインの対応状況を確認する必要がある。","url":"https://flutter.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('react-native-expo', 1, 'mobile-desktop', 'tool', 'React Native＋Expo', 'Reactの知識を使ってiOS・Androidアプリを開発する', '{"overview":"Reactの知識でネイティブアプリを開発できるフレームワーク。Expoを使うとビルド・配布の設定が簡略化される。","fit":"Web版で既にReactを使っているチームが、モバイルアプリも同じ技術で開発したい場合に向く。","caution":"高度なネイティブ機能を使う場合はExpoの管理外（Bare workflow）に切り替える必要が出ることがある。","url":"https://reactnative.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('swift-kotlin', 1, 'mobile-desktop', 'tool', 'Swift・Kotlin', 'iOS・Android固有の機能や性能を重視したネイティブアプリを開発する', '{"overview":"iOS（Swift）・Android（Kotlin）それぞれの公式言語でアプリを個別に開発する方式。","fit":"OS標準機能への即応性や描画パフォーマンスを最優先したいアプリに向く。","caution":"iOS・Androidを別々に実装するため、開発・保守コストが最も高くなりやすい。"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('react-tauri', 1, 'mobile-desktop', 'tool', 'React＋Tauri', '軽量なWindows・Mac向けデスクトップアプリを開発する', '{"overview":"ReactなどのWeb技術でUIを作り、Rust製の軽量ランタイム（Tauri）でデスクトップアプリとして動かす構成。","fit":"Electronより軽量・省メモリなデスクトップアプリを作りたい場合に向く。","caution":"OS固有機能を使う際は、Rustコマンド側の実装が必要になる場面がある。","url":"https://tauri.app/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('react-electron', 1, 'mobile-desktop', 'tool', 'React＋Electron', 'Node.jsやWeb技術を使って高機能なデスクトップアプリを開発する', '{"overview":"ReactなどのWeb技術とNode.jsでデスクトップアプリを構築するフレームワーク。ブラウザエンジンを内包する。","fit":"Node.jsのAPIをフル活用した高機能な業務アプリを、Web技術のまま作りたい場合に向く。","caution":"アプリのサイズやメモリ使用量が大きくなりやすい。","url":"https://www.electronjs.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('flet', 1, 'mobile-desktop', 'tool', 'Flet', 'Pythonを使って、Web・デスクトップ・モバイルで動く業務ツールを構築する', '{"overview":"Pythonで画面や処理を記述し、Web・Windows・macOS・モバイル向けに展開できるUIフレームワーク。","fit":"Pythonによるデータ処理や業務処理に、比較的短期間で操作画面を追加したい場合に向く。","caution":"複雑な画面デザインや高度なネイティブ機能では、React、Flutter、PySideなどに比べて調整が必要になることがある。","url":"https://flet.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('pyside', 1, 'mobile-desktop', 'tool', 'PySide', 'Pythonで高機能なWindows・Mac・Linux向けデスクトップアプリを構築する', '{"overview":"Qtの公式Pythonバインディング。ネイティブに近いデスクトップUIや、ファイル・端末機能を扱うアプリを構築できる。","fit":"画面数が多い業務アプリや、端末内で完結する高機能なデスクトップツールに向く。","caution":"Qt固有の設計やイベント処理を理解する必要があり、Fletより学習コストが高い。","url":"https://doc.qt.io/qtforpython/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('capacitor', 1, 'mobile-desktop', 'tool', 'Capacitor', '既存のReact・VueなどのWebアプリを、iOS・Androidアプリとして配布する', '{"overview":"Webアプリをネイティブアプリのコンテナ内で動かし、カメラ、通知、位置情報などの端末機能へアクセスできるクロスプラットフォームランタイム。","fit":"すでにWebアプリがあり、そのコードを活かしてモバイルアプリとしてストア配布したい場合に向く。","caution":"高度な描画性能や複雑なネイティブ機能を必要とするアプリでは、Flutter、React Native、Swift・Kotlinの方が適する場合がある。","url":"https://capacitorjs.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-data-api', 1, 'backend', 'tool', 'Supabase Data API', 'PostgreSQLのデータを、独自APIを作らずにWeb・アプリから操作する', '{"overview":"SupabaseのPostgreSQLに対して、自動生成されるREST APIやクライアントSDKを使ってデータを読み書きする仕組み。GraphQL APIも利用できる。","fit":"独自のAPIサーバーを持たず、フロント・アプリから直接データ操作をしたいMVP開発に向く。","caution":"クライアントから直接データを操作する場合は、Row Level Securityによるアクセス制御が必須。複雑な業務処理はEdge Functionsや独立したAPIと組み合わせる。","url":"https://supabase.com/docs/guides/api"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-edge-functions', 1, 'backend', 'tool', 'Supabase Edge Functions', 'サーバーレス環境で外部API連携や秘密情報を扱う処理を実行する', '{"overview":"Supabase上で動くサーバーレス関数（Deno）。APIキーなど秘密情報を扱う処理や外部API連携を実行できる。","fit":"決済処理や通知送信など、クライアントに公開できない処理を安全に実行したい場合に向く。","caution":"常時稼働のバッチ処理や長時間処理には向かず、実行時間の制限がある。","url":"https://supabase.com/docs/guides/functions"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nextjs-server-actions', 1, 'backend', 'tool', 'Next.js Server Actions・Route Handlers', 'Next.js内でフォーム処理、DB操作、API処理を実装する', '{"overview":"Next.jsアプリ内でサーバー側の処理（フォーム送信、DB操作など）を関数として直接呼び出せる機能。","fit":"別途APIサーバーを構築せず、Next.js単体でフルスタックに完結させたい場合に向く。","caution":"Next.jsのバージョンやレンダリング方式への依存が強く、他フレームワークへの移植性は低い。","url":"https://nextjs.org/docs"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nestjs', 1, 'backend', 'tool', 'NestJS', '複雑な業務ロジックや外部連携を持つ、構造化されたAPIを構築する', '{"overview":"TypeScript製のサーバーフレームワーク。モジュール・DIなどAngularに近い設計思想で、大規模なAPIを構造化しやすい。","fit":"複数の業務ロジックや外部連携が絡む、規模の大きい業務システムのAPIに向く。","caution":"小規模なAPIには記述量が多く、オーバースペックになりやすい。","url":"https://nestjs.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('fastapi', 1, 'backend', 'tool', 'FastAPI', 'Pythonで高速なAPI、AI処理、データ処理を構築する', '{"overview":"Python製の高速なAPIフレームワーク。型ヒントを活用した自動バリデーションやAPIドキュメント生成が特徴。","fit":"AI・データ処理系のライブラリ（Python資産）を活かしたAPIやRAG基盤の構築に向く。","caution":"TypeScript系フロントとの型共有がしづらく、フロント・バック間でスキーマ管理の工夫が必要。","url":"https://fastapi.tiangolo.com/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 4);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('cloud-functions', 1, 'backend', 'tool', 'Cloud Functions', 'FirebaseやGoogle Cloud上で、認証、通知、定期処理、外部連携を実行する', '{"overview":"FirebaseやGoogle Cloud上で動くサーバーレス関数。認証イベントやデータ更新をトリガーに処理を実行できる。","fit":"Firebase・Firestoreと連携した通知処理や定期バッチ処理に向く。","caution":"コールドスタートによる遅延や、関数間の処理の見通しにくさに注意が必要。","url":"https://cloud.google.com/functions"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 5);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('aspnet-core', 1, 'backend', 'tool', 'ASP.NET Core', 'C#で企業向けAPIやMicrosoft環境と連携するシステムを構築する', '{"overview":"MicrosoftのC#製サーバーフレームワーク。高いパフォーマンスとエンタープライズ向け機能を備える。","fit":"既存のMicrosoft環境（Active Directory、SQL Server等）と密に連携する企業システムに向く。","caution":".NETエコシステム前提のため、非Microsoft環境のチームには習得コストがかかる。","url":"https://dotnet.microsoft.com/en-us/apps/aspnet"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 6);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('aws-lambda', 1, 'backend', 'tool', 'AWS Lambda＋API Gateway', 'アクセス量に応じて自動拡張するサーバーレスAPIを構築する', '{"overview":"AWSのサーバーレス関数実行環境。API Gatewayと組み合わせてHTTP APIを構築できる。","fit":"アクセス量が変動する処理や、使った分だけ課金したいAPIに向く。","caution":"実行時間やメモリの制限があり、常時接続が必要な処理には不向き。","url":"https://aws.amazon.com/lambda/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 7);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('azure-functions', 1, 'backend', 'tool', 'Azure Functions', 'Azure上でサーバーレス処理やMicrosoftサービス連携を実行する', '{"overview":"Azure上のサーバーレス関数実行環境。Azure内の各種サービスとのトリガー連携が豊富。","fit":"Microsoft 365やAzure ADなど、既存のAzure環境と連携する処理に向く。","caution":"AWS Lambdaと同様に実行時間の制限があり、長時間処理には工夫が必要。","url":"https://azure.microsoft.com/en-us/products/functions"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 8);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('rust-command', 1, 'backend', 'tool', 'Rustコマンド', 'Tauriアプリから端末のファイルやOS機能を安全かつ高速に操作する', '{"overview":"Tauriアプリからネイティブの処理（ファイル操作やOS機能）を呼び出すためのRust実装部分。","fit":"Tauriアプリでファイルシステムや高速な演算処理を安全に扱いたい場合に向く。","caution":"Rustの学習コストがあり、Web技術のみのチームには追加のスキルセットが必要。","url":"https://www.rust-lang.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 9);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('nodejs', 1, 'backend', 'tool', 'Node.js', 'Electronアプリでファイル操作、外部API連携、端末処理を行う', '{"overview":"Electronアプリのメインプロセスとして、ファイル操作や外部API連携、OS機能へのアクセスを担うランタイム。","fit":"Web技術の知識のまま、デスクトップアプリのバックエンド処理を実装したい場合に向く。","caution":"メインプロセスの処理が重いとアプリ全体の応答性に影響するため、非同期処理の設計が重要。","url":"https://nodejs.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 10);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('hono', 1, 'backend', 'tool', 'Hono', 'TypeScriptで軽量なAPI、Webhook、BFF、エッジ処理を構築する', '{"overview":"Web標準を基盤とした軽量なTypeScript向けWebフレームワーク。Cloudflare Workers、Node.js、Deno、Bun、AWS Lambdaなど複数の実行環境に対応する。","fit":"小規模API、Webhook受信、フロントエンド向けBFF、エッジ環境で動くAPIを素早く構築したい場合に向く。","caution":"大規模な業務システムでは、NestJSのようなモジュール構造が標準化されたフレームワークの方が管理しやすい場合がある。","url":"https://hono.dev/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 11);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-realtime', 1, 'backend', 'tool', 'Supabase Realtime', 'チャット、オンライン状態、共同編集、データ更新のリアルタイム反映を実装する', '{"overview":"Supabaseが提供するリアルタイム通信機能。Broadcast、Presence、PostgreSQLの変更通知などを利用できる。","fit":"チャット、通知、ユーザーのオンライン状態、複数ユーザー間のリアルタイム更新が必要なWeb・モバイルアプリに向く。","caution":"同時接続数、メッセージ数、通信量、再接続、イベントの重複、処理順序を考慮した設計が必要。","url":"https://supabase.com/docs/guides/realtime"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 12);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('supabase-postgresql', 1, 'database', 'tool', 'Supabase PostgreSQL', '顧客、案件、商品、注文など、関係性のあるデータを管理する', '{"overview":"SupabaseがマネージドでホスティングするPostgreSQL。認証・API・ストレージなどSupabaseの他機能と統合されている。","fit":"顧客・案件・商品などリレーショナルなデータを、他のSupabase機能と併せて手早く管理したい場合に向く。","caution":"大規模な負荷対策やチューニングの自由度は、自前運用のPostgreSQLより制限される。","url":"https://supabase.com/docs/guides/database"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 0);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('postgresql', 1, 'database', 'tool', 'PostgreSQL', '複雑な業務データ、検索、集計、トランザクションを管理する', '{"overview":"オープンソースのリレーショナルデータベース。トランザクション・複雑な検索・拡張機能に強い。","fit":"複雑な業務データや集計処理、将来的な拡張（pgvector等）を見据えた基盤として向く。","caution":"自前で運用する場合はバックアップ・スケーリングなどの運用設計が別途必要。","url":"https://www.postgresql.org/"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 1);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('firestore', 1, 'database', 'tool', 'Firestore', 'モバイル・Web間でデータをリアルタイム同期し、オフラインでも利用する', '{"overview":"Firebaseが提供するNoSQL型データベース。クライアントからのリアルタイム同期とオフラインキャッシュに強い。","fit":"モバイル・Web間でデータをリアルタイムに同期したいアプリや、オフライン対応が必要なアプリに向く。","caution":"複雑な集計やJOINに近い操作は不得意で、リレーショナルなデータ設計には工夫が必要。","url":"https://firebase.google.com/docs/firestore"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 2);
INSERT INTO registry_technologies (id, release_id, category_id, technology_kind, name, description, details_json, security_score, cost_score, development_speed_score, ai_coding_score, scalability_score, status, notes, sort_order) VALUES ('cloud-sql', 1, 'database', 'tool', 'Cloud SQL', 'Google Cloud上でPostgreSQLやMySQLなどのリレーショナルDBを運用する', '{"overview":"Google CloudのマネージドリレーショナルDBサービス。PostgreSQL・MySQLを選んで運用できる。","fit":"Google Cloud上でPostgreSQL・MySQLを本格運用したい場合に向く。","caution":"サーバーレスではないため、インスタンスサイズ選定などの運用管理が必要。","url":"https://cloud.google.com/sql"}', NULL, NULL, NULL, NULL, NULL, 'active', NULL, 3);
